<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller;
use App\Tenancy\TenantContext;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
class DashboardController extends Controller { public function __invoke(Request $r, TenantContext $tenant) { $tid=$tenant->id(); $branch=$r->query('BranchId'); $scope=fn($q)=>$q->where('TenantId',$tid)->when($branch,fn($x)=>$x->where('BranchId',$branch)); $students=$scope(DB::table('Students')); $attendance=$scope(DB::table('Attendance'))->whereDate('AttendanceDate',today()); $payments=$scope(DB::table('Payments'))->where('Status','Completed'); return response()->json(['success'=>true,'message'=>'Dashboard metrics retrieved.','data'=>['TotalStudents'=>(clone $students)->where('Status','Active')->count(),'TotalClasses'=>$scope(DB::table('Classes'))->where('Status','Active')->count(),'TotalTeachers'=>$scope(DB::table('Employees'))->where('IsTeacher',true)->where('Status','Active')->count(),'PresentToday'=>(clone $attendance)->where('Status','Present')->count(),'AbsentToday'=>(clone $attendance)->where('Status','Absent')->count(),'OrphanStudents'=>(clone $students)->where('WelfareStatus','Orphan')->count(),'FreeScholarships'=>(clone $students)->where('WelfareStatus','Sponsored')->count(),'FeesCollectedToday'=>(clone $payments)->whereDate('CreatedAt',today())->sum('Amount'),'FeesCollectedThisMonth'=>(clone $payments)->whereBetween('CreatedAt',[now()->startOfMonth(),now()->endOfMonth()])->sum('Amount'),'OutstandingInvoices'=>$scope(DB::table('Invoices'))->where('Balance','>',0)->sum('Balance'),'TotalExpenses'=>$scope(DB::table('Expenses'))->where('Status','!=','Draft')->whereBetween('ExpenseDate',[now()->startOfMonth(),now()->endOfMonth()])->sum('Amount'),'TotalDiscounts'=>DB::table('StudentDiscounts')->where('TenantId',$tid)->where('IsActive',true)->sum('FixedAmount'),'QuranAssignmentsCompleted'=>$scope(DB::table('QuranAssignments'))->where('Status','Completed')->count(),'OverdueQuranAssignments'=>$scope(DB::table('QuranAssignments'))->where('DueDate','<',today())->whereNotIn('Status',['Completed','Cancelled'])->count(),'RecentPayments'=>$scope(DB::table('Payments'))->orderByDesc('PaymentId')->limit(5)->get(),'RecentAdmissions'=>(clone $students)->orderByDesc('StudentId')->limit(5)->get()],'meta'=>['filters'=>$r->only(['BranchId','AcademicYearId','ShiftId','LevelId','ClassId','From','To'])]]); } }
